#[test]
fn test_full_2_correct_order() -> Result<(), Box<dyn std::error::Error>> {
    let wf = fixture_with_input_slots(vec![
        CompiledInputSlot { slot: 2, kind: InputSlotKind::I64 },
        CompiledInputSlot { slot: 3, kind: InputSlotKind::Bool },
    ])?;
    let bytes = serialize_slot_values(vec![
        slot_value_i64(10),
        slot_value_bool(true),
    ])?;
    let result = map_runtime_inputs(&wf, &bytes);
    assert!(result.is_ok(), "expected Ok");
    let mapped = result?;
    assert_eq!(mapped.len(), 2);
    assert_eq!(mapped[0].0, 2);
    match &mapped[0].1 {
        SlotValue::I64(n) => assert_eq!(*n, 10),
        other => panic!("expected I64 value, got {other:?}"),
    }
    assert_eq!(mapped[1].0, 3);
    match &mapped[1].1 {
        SlotValue::Bool(b) => assert_eq!(*b, true),
        other => panic!("expected Bool value, got {other:?}"),
    }
    Ok(())
}

#[test]
fn test_wrong_kind_at_slot2() -> Result<(), Box<dyn std::error::Error>> {
    let wf = fixture_with_input_slots(vec![
        CompiledInputSlot { slot: 2, kind: InputSlotKind::I64 },
    ])?;
    let bytes = serialize_slot_values(vec![slot_value_bool(true)])?;
    let result = map_runtime_inputs(&wf, &bytes);
    assert!(result.is_err(), "expected error");
    let err = result.unwrap_err();
    assert_eq!(
        err,
        InputMappingError::KindMismatch {
            slot: 2,
            expected_kind: InputSlotKind::I64,
        }
    );
    Ok(())
}

